const body = $input.first().json.body ?? {};
const errors = [];
const TYPES = ['price_change', 'stock_change', 'product_added', 'discount_started', 'discount_ended'];
const type = String(body.event_type ?? '').toLowerCase().trim();
if (!TYPES.includes(type)) errors.push('event_type must be one of: ' + TYPES.join(', '));
const sku = String(body.sku ?? '').trim();
if (!sku) errors.push('sku is required');
const supplier = String(body.supplier ?? '').trim();
if (!supplier) errors.push('supplier is required');
const name = String(body.product_name ?? '').trim();
const currency = String(body.currency ?? '').trim();
const category = String(body.category ?? '').trim();

const num = (v) => (v === null || v === undefined || v === '' || Number.isNaN(Number(v))) ? null : Number(v);
const money = (label, v) => { const n = num(v); if (n === null || n < 0) errors.push(label + ' must be a non-negative number'); return n; };
const count = (label, v) => { const n = num(v); if (n === null || n < 0 || !Number.isInteger(n)) errors.push(label + ' must be a non-negative integer'); return n; };

let oldVal = null, newVal = null, discountPct = null, stock = null;
if (type === 'price_change' || type === 'discount_ended') {
  oldVal = money('old_price', body.old_price); newVal = money('new_price', body.new_price);
} else if (type === 'stock_change') {
  oldVal = count('old_stock', body.old_stock); newVal = count('new_stock', body.new_stock);
} else if (type === 'product_added') {
  if (!name) errors.push('product_name is required for product_added');
  newVal = money('price', body.price); stock = count('stock', body.stock);
} else if (type === 'discount_started') {
  oldVal = money('old_price', body.old_price); newVal = money('new_price', body.new_price);
  discountPct = num(body.discount_pct);
  if (discountPct === null || discountPct < 1 || discountPct > 90) errors.push('discount_pct must be between 1 and 90');
  if (oldVal !== null && newVal !== null && newVal >= oldVal) errors.push('new_price must be lower than old_price for a discount');
}

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
if (errors.length) {
  return [{ json: {
    valid: false, errors,
    message: '⛔ <b>Malformed supplier event rejected</b>\n' + errors.map(e => '• ' + esc(e)).join('\n') +
             '\n\n<code>' + esc(JSON.stringify(body).slice(0, 500)) + '</code>'
  } }];
}

const pct = (oldVal === null || oldVal === 0 || newVal === null) ? null : Math.round(((newVal - oldVal) / oldVal) * 1000) / 10;
let severity = 'info';
if (type === 'stock_change') severity = newVal === 0 ? 'critical' : (newVal <= 5 ? 'warning' : 'info');
else if (type === 'price_change' && pct !== null) severity = Math.abs(pct) >= 20 ? 'critical' : (Math.abs(pct) >= 10 ? 'warning' : 'info');
else if (type === 'discount_started') severity = discountPct >= 40 ? 'warning' : 'info';
else if (type === 'product_added' && stock === 0) severity = 'warning';

const icon = { info: 'ℹ️', warning: '⚠️', critical: '🚨' }[severity];
const cur = currency ? currency + ' ' : '';
const money_ = (v) => cur + Number(v).toLocaleString('en-US');
const head = { price_change: 'Price change', stock_change: 'Stock change', product_added: '🆕 New product listed', discount_started: '🏷️ Discount started', discount_ended: '🔚 Discount ended' }[type];
const arrow = (type === 'price_change' || type === 'stock_change') ? (newVal > oldVal ? ' 📈' : (newVal < oldVal ? ' 📉' : ' ➖')) : '';
let lines = `<b>Supplier:</b> ${esc(supplier)}\n<b>SKU:</b> ${esc(sku)}` + (name ? `\n<b>Product:</b> ${esc(name)}` : '');
if (type === 'price_change' || type === 'discount_ended') lines += `\n<b>Was:</b> ${esc(money_(oldVal))}\n<b>Now:</b> ${esc(money_(newVal))}` + (pct !== null ? `\n<b>Change:</b> ${pct > 0 ? '+' : ''}${pct}%` : '');
if (type === 'stock_change') lines += `\n<b>Was:</b> ${oldVal} units\n<b>Now:</b> ${newVal} units` + (pct !== null ? `\n<b>Change:</b> ${pct > 0 ? '+' : ''}${pct}%` : '');
if (type === 'product_added') lines += `\n<b>Price:</b> ${esc(money_(newVal))}\n<b>Stock:</b> ${stock} units` + (category ? `\n<b>Category:</b> ${esc(category)}` : '');
if (type === 'discount_started') lines += `\n<b>Regular:</b> ${esc(money_(oldVal))}\n<b>Discounted:</b> ${esc(money_(newVal))}\n<b>Discount:</b> ${discountPct}% off`;
const message = `${icon} <b>${head}</b>${arrow}\n${lines}\n<b>Severity:</b> ${severity}`;

return [{ json: {
  valid: true, errors: [],
  event_type: type, sku, supplier, product_name: name,
  old_value: oldVal, new_value: newVal, change_pct: pct, currency, severity,
  received_at: new Date().toISOString(), raw_payload: JSON.stringify(body), message
} }];
